def solve_append(xs, ys, zs):
    if zs is None:
        if xs is None or ys is None:
            raise ValueError("unbounded: give the whole, or both parts")
        return [(tuple(xs), tuple(ys), tuple(xs) + tuple(ys))]
    zs = tuple(zs)
    out = []
    for i in range(len(zs) + 1):
        head, tail = zs[:i], zs[i:]
        if xs is not None and tuple(xs) != head:
            continue
        if ys is not None and tuple(ys) != tail:
            continue
        out.append((head, tail, zs))
    return out
